package com.eventhub.controller; import com.eventhub.dto.AuditLogResponse; import com.eventhub.service.AuditLogService; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Page; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/audit-logs") @RequiredArgsConstructor @PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN')") public class AuditLogController {private final AuditLogService service; @GetMapping public Page<AuditLogResponse> list(@RequestParam(required=false)String action,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){return service.list(action,page,size);}}
